const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
function flatten(nodes:DesignNode[],parentId?:string,depth=0):FlatNode[]{return nodes.flatMap((node,index)=>[{node,parentId,depth,index},...flatten(node.children||[],node.id,depth+1)]);}
function layerIcon(type:string){const Icon=({text:Type,image:Image,container:Frame,instance:Component,html:Code,svg:Code,shape:Square} as Record<string,typeof Layers>)[type]||Layers;return <Icon size={14}/>;}
