function uploadStore<T>(action:(store:IDBObjectStore)=>IDBRequest<T>):Promise<T>{
 return new Promise((resolve,reject)=>{const request=indexedDB.open('leafloom-design-pending',1);request.onupgradeneeded=()=>request.result.createObjectStore('uploads');request.onerror=()=>reject(request.error);request.onsuccess=()=>{const db=request.result,tx=db.transaction('uploads','readwrite');let result:T;const work=action(tx.objectStore('uploads'));work.onsuccess=()=>{result=work.result;};tx.oncomplete=()=>{db.close();resolve(result);};tx.onerror=()=>{db.close();reject(tx.error);};tx.onabort=()=>{db.close();reject(tx.error);};};});
}

