function IconButton({label,children,onClick,disabled=false}:{label:string,children:React.ReactNode,onClick:()=>void,disabled?:boolean}){return <button type="button" className="dw-icon" aria-label={label} title={label} onClick={onClick} disabled={disabled}>{children}</button>;}

function starter(kind:string):DesignNode{
 const node=emptyNode('container',t(kind));node.style={...node.style,width:kind==='图鉴网格'?620:kind==='弹窗'?400:360,height:kind==='图鉴网格'?520:kind==='弹窗'?300:110,background:'#ffffff',borderRadius:20,padding:20,display:'flex',gap:12,alignItems:'center',boxShadow:'0 8px 24px #18253a18'};
 const text=(name:string,value:string,x=0,y=0)=>({...emptyNode('text',t(name),x,y),style:{x,y,width:200,height:36,fontSize:24,color:'#263a46'},props:{text:value}});
 if(kind==='HUD'||kind==='资源计数'){node.children=[text('资源计数','★  1280'),text('生命值','♥  5')];}
 else if(kind==='进度条'){node.style={...node.style,height:36,padding:4,background:'#e0e8df'};const fill=emptyNode('shape',t('进度'));fill.style={x:0,y:0,width:240,height:28,background:'#72ad81',borderRadius:18};node.children=[fill];}
 else if(kind==='图鉴网格'){node.style={...node.style,display:'grid',gridTemplateColumns:'repeat(3, 1fr)',alignItems:'stretch'};node.children=Array.from({length:9},(_,index)=>({...emptyNode('button',t('角色卡')),style:{width:175,height:140,background:'#f1f5ed',borderRadius:16,fontSize:20},props:{text:'★ '+(index+1)}}));}
 else if(kind==='弹窗'){node.style={...node.style,display:'flex',flexDirection:'column',justifyContent:'center'};node.children=[text('标题',t('设置')),{...emptyNode('button',t('关闭')),style:{width:220,height:48,background:'#345f52',color:'#fff',borderRadius:12},props:{text:t('关闭'),action:'close'}}];}
 else if(kind==='页签'){node.style={...node.style,height:76};node.children=[t('首页'),t('图鉴'),t('设置')].map(value=>({...emptyNode('button',value),style:{width:100,height:40,background:'#edf2ed',borderRadius:12},props:{text:value}}));}
 else if(kind==='角色卡'){node.style={...node.style,width:240,height:260,flexDirection:'column'};node.children=[{...emptyNode('shape',t('角色')),style:{width:160,height:160,background:'#f2d8ad',borderRadius:'50%'}},text('角色名称',t('新角色'))];}
 else{node.style={...node.style,height:180,justifyContent:'center'};node.children=[text('状态',t(kind))];}
 return node;
}

