 useEffect(()=>{const paste=(event:ClipboardEvent)=>{if(preview)return;if((event.target as HTMLElement)?.closest('input,textarea,[contenteditable="true"]'))return;const files=Array.from(event.clipboardData?.files||[]);if(files.length){event.preventDefault();void chooseFiles(files);}};const key=(event:KeyboardEvent)=>{if(preview){if(event.key==='Escape'){event.preventDefault();stopPreview();}return;}if((event.target as HTMLElement)?.closest('input,textarea,select,[contenteditable="true"]'))return;const modifier=event.metaKey||event.ctrlKey;if(!modifier&&!event.altKey&&!preview){if(selection.length&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();send({type:'studio-action',action:'nudge-'+event.key.slice(5).toLowerCase()+(event.shiftKey?'-large':'')});return;}if(event.key.toLowerCase()==='v')setTool('select');if(event.key.toLowerCase()==='h')setTool('hand');if(event.shiftKey&&event.code==='Digit1'){event.preventDefault();send({type:'studio-fit'});}if(event.shiftKey&&event.code==='Digit2'){event.preventDefault();send({type:'studio-fit',selection:true});}}if(modifier&&event.key.toLowerCase()==='z'){event.preventDefault();runtimeAction.current(event.shiftKey?'redo':'undo');}if(modifier&&event.key.toLowerCase()==='y'){event.preventDefault();runtimeAction.current('redo');}if(modifier&&event.key.toLowerCase()==='d'){event.preventDefault();duplicateSelection();}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();deleteSelection();}if(event.key==='Escape'){setPreview(false);setSelected([]);}};window.addEventListener('paste',paste);window.addEventListener('keydown',key);return()=>{window.removeEventListener('paste',paste);window.removeEventListener('keydown',key);};},[selection,page?.id,preview,send]);
